style.css:
@-moz-document url-prefix("https://discord.com"), url-prefix("https://canary.discord.com"), url-prefix("https://ptb.discord.com") {
/* Background Image */
    body {
        background: url(https://www.vice.com/wp-content/uploads/sites/2/2021/02/1611779956370-screen-shot-2021-01-27-at-33858-pm.png?resize=1024,497) no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Add a Dark Overlay to Improve Readability */
    .appMount-3lHmkl::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0, 0, 0, 0.5); /* Adjust transparency if needed */
        z-index: -1;
    }

    /* Fix Search Bar & UI Readability */
    .searchBar-6Kv8R2, 
    .container-1D34oG, /* Friends List */
    .channelTextArea-1FufC0, /* Message Input */
    .sidebar-1tnWFu, /* Left Sidebar */
    .chat-2ZfjoI, /* Chat Area */
    .membersWrap-3NUR2t { /* Member List */
        background: rgba(0, 0, 0, 0.6) !important; /* Darken elements */
        border-radius: 5px !important;
    }

    /* Improve Text Visibility */
    .theme-dark, .theme-light {
        --header-primary: #ffffff !important;
        --header-secondary: #bbbbbb !important;
        --text-normal: #ffffff !important;
        --text-muted: #cccccc !important;
        --channels-default: #ffffff !important;
        --interactive-normal: #ffffff !important;
        --interactive-hover: #dddddd !important;
        --interactive-active: #ffffff !important;
        --interactive-muted: #aaaaaa !important;
    }

    /* Fix Pop-ups and Modals */
    .modal-yWgWj-, 
    .footer-3rDWdC {
        background: rgba(0, 0, 0, 0.8) !important;
    }

    /* Scrollbar Styling */
    .scrollbar-2rkZSL {
        width: 8px !important;
    }

    .thumb-2JwNFC {
        background: rgba(255, 255, 255, 0.3) !important;
    }

    .track-1JN30G,
    .thumb-2JwNFC {
        border: none !important;
    }
}
